#endif

void main() {
    uint waveM = gl_SubgroupID / WAVES_N;
    uint waveN = gl_SubgroupID % WAVES_N;

    uint wm0 = gl_WorkGroupID.y * BM + waveM * (WM * TILE);
    uint wn0 = gl_WorkGroupID.x * BN + waveN * (WN * TILE);

